<?php
require __DIR__.'/config.php';$pdo=db();$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST' && $count===0){verify_csrf();$user=trim($_POST['username']??'');$pass=$_POST['password']??'';if(strlen($user)<3||strlen($pass)<8){$msg='Username อย่างน้อย 3 ตัว และ Password อย่างน้อย 8 ตัว';}else{$st=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$st->execute([$user,password_hash($pass,PASSWORD_DEFAULT)]);$msg='สร้าง Admin สำเร็จ กรุณาลบไฟล์ create_admin.php หลังใช้งาน';$count=1;}}
?><!doctype html><html lang="th"><head><meta charset="utf-8"><title>Create Admin</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="auth-wrap"><div class="card"><h1>สร้างผู้ดูแลระบบครั้งแรก</h1><?php if($msg):?><div class="alert"><?=h($msg)?></div><?php endif;?><?php if($count>0):?><p>มีบัญชี Admin แล้ว ไม่อนุญาตให้สร้างผ่านหน้านี้อีก</p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="btn">สร้าง Admin</button></form><?php endif;?></div></main></body></html>